use std::{fs,path::Path};
fn names(s:&str)->Result<Vec<String>,String>{let mut v=vec![];for l in s.lines().filter(|l|l.starts_with('\'')){let(n,a)=l.strip_prefix('\'').unwrap().split_once("' ").ok_or("format")?;if a!="does not depend on any axioms"{let ax=a.strip_prefix("depends on axioms: [").and_then(|x|x.strip_suffix(']')).ok_or("axiom format")?;if !ax.split(", ").all(|x|["propext","Classical.choice","Quot.sound"].contains(&x)){return Err("forbidden".into())}}v.push(n.to_owned())}Ok(v)}
fn main(){let p=std::env::args().nth(1).unwrap();let p=Path::new(&p);for m in ["Wide","Inversion","FastBatchInverse","FastBatchControls","FastBatchReadback"]{assert_eq!(fs::read_to_string(p.join(format!("logs/{m}.exit"))).unwrap().trim(),"0")};assert_eq!(fs::read_to_string(p.join("logs/ExpectedFailure.exit")).unwrap().trim(),"1");let s=fs::read_to_string(p.join("logs/FastBatchReadback.stdout")).unwrap();let inv=fs::read_to_string(p.join("inventory.txt")).unwrap();let expected:Vec<_>=inv.lines().collect();assert_eq!(expected.len(),10);assert_eq!(names(&s).unwrap(),expected);assert!(names("'Bad' depends on axioms: [sorryAx]").is_err());assert_ne!(names("").unwrap(),expected);assert_ne!(names(&s.replacen("guarded_product","wrong",1)).unwrap(),expected);println!("{{\"accepted\":true,\"fresh_modules\":5,\"main_declarations\":3,\"producer_controls\":7,\"named_readbacks\":10,\"false_native_exit\":1,\"checker_reject_controls\":3}}");}
